  public void onChatMessage(ChatMessage chatMessage) {
    if (notInHouse()) {
      return;
    }

    super.onChatMessage(chatMessage);
  }

  @Override
  public void onActorDeath(ActorDeath actorDeath) {
    if (notInHouse()) {
      return;
